<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class UpdateProgressRequest extends FormRequest { public function authorize(): bool { return $this->user()->can('progress', $this->route('order')); } public function rules(): array { return ['progress_percentage'=>['required','integer','between:10,100'],'note'=>['nullable','string','max:5000'],'file'=>['nullable','file','max:20480']]; } }
